// Banques de questions des quiz intégrés aux articles (pilote : 3 articles).
// Chaque article a une banque de 8 questions ; à chaque partie, le composant
// tire 5 questions au hasard et mélange l'ordre des réponses.
// Ton : tutoiement, comme la charte de ton.

export interface QuestionQuiz {
  question: string;
  choix: string[];
  /** Index de la bonne réponse dans `choix` (avant mélange). */
  bonne: number;
  explication: string;
}

